class StretchReleaseContract(unittest.TestCase):
    def test_requests_and_negative_controls_for_all_qualification_topics(self):
        for topic,text,expected in FIXTURES:
            with self.subTest(topic=topic,text=text):
                self.assertEqual(runner.stretch_triggered({'Topic':topic},text),expected)

    def test_each_topic_preserves_initial_state_then_changes_once(self):
        seen=set()
        for topic,text,expected in FIXTURES:
            if not expected or topic in seen: continue
            seen.add(topic)
            case={'Case':'STATE', 'domain':'Eye', 'First Line for Alan':'symptom', 'History':'baseline context',
                  'stretch':{'Topic':topic,'Target field(s)':'History','Start (hidden)':'INITIAL',
                             'Updated (hidden)':'UPDATED','Unchanged facts':{'History':'baseline context'}}}
            with self.subTest(topic=topic):
                controller=runner.CaseFilter(case)
                self.assertIsNone(controller.view_for_turn('Any fever?').state_transition)
                before=str(controller.visible_facts())
                self.assertIn('INITIAL',before)
                self.assertNotIn('UPDATED',before)
                self.assertIn('baseline context',before)
                self.assertEqual(controller.view_for_turn(text).state_transition,'STATE')
                after=str(controller.visible_facts())
                self.assertIn('UPDATED',after)
                self.assertNotIn('INITIAL',after)
                self.assertIn('baseline context',after)
                self.assertIsNone(controller.view_for_turn(text).state_transition)
        self.assertEqual(len(seen),20)
